begin;
set local search_path=public,extensions;
select plan(30);

select ok((select count(*)=5 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relkind='r'and c.relname=any(array['diagnostic_runs','diagnostic_subscores','diagnostic_anomalies','diagnostic_recommendations','diagnostic_opportunities'])),'five P07 persistence tables exist');
select ok((select count(*)=5 and bool_and(c.relrowsecurity)from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relname=any(array['diagnostic_runs','diagnostic_subscores','diagnostic_anomalies','diagnostic_recommendations','diagnostic_opportunities'])),'RLS is enabled on every P07 table');
select ok((select count(*)=5 from pg_policies where schemaname='public'and tablename=any(array['diagnostic_runs','diagnostic_subscores','diagnostic_anomalies','diagnostic_recommendations','diagnostic_opportunities'])),'each P07 table has an explicit scoped read policy');
select ok(not has_table_privilege('authenticated','public.diagnostic_runs','INSERT')and not has_table_privilege('authenticated','public.diagnostic_opportunities','UPDATE'),'authenticated users cannot bypass commands');
select ok(not has_table_privilege('anon','public.diagnostic_runs','SELECT')and not has_table_privilege('anon','public.diagnostic_opportunities','SELECT'),'anonymous users cannot read diagnostic data');
select ok((select count(*)=2 and bool_and(p.prosecdef and p.proconfig::text like'%search_path=%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['complete_diagnostic_session','transition_diagnostic_opportunity'])),'commands are security definer with fixed search paths');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['complete_diagnostic_session','transition_diagnostic_opportunity'])and(has_function_privilege('anon',p.oid,'EXECUTE')or has_function_privilege('service_role',p.oid,'EXECUTE'))),'anon and service roles cannot execute P07 user commands');
select ok((select count(*)=2 and bool_and(has_function_privilege('authenticated',p.oid,'EXECUTE'))from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['complete_diagnostic_session','transition_diagnostic_opportunity'])),'authenticated receives only explicit commands');
select ok(not exists(select 1 from information_schema.columns where table_schema='public'and table_name like'diagnostic_%'and data_type in('real','double precision')),'P07 contains no floating point score or money');
select is((select data_type from information_schema.columns where table_schema='public'and table_name='diagnostic_runs'and column_name='overall_score'),'numeric','overall score is exact numeric');
select ok(exists(select 1 from pg_constraint where conrelid='public.diagnostic_runs'::regclass and contype='c'and pg_get_expr(conbin,conrelid)like'%overall_score%'and pg_get_expr(conbin,conrelid)like'%0%'and pg_get_expr(conbin,conrelid)like'%100%'),'score boundaries are constrained');
select ok((select indexdef like'%WHERE (status = ''COMPLETED''%'from pg_indexes where schemaname='public'and indexname='diagnostic_one_current_per_session_uidx'),'only one current result exists per submitted session');
select ok((select count(*)=4 from pg_trigger where tgname=any(array['diagnostic_runs_immutable','diagnostic_subscores_immutable','diagnostic_anomalies_immutable','diagnostic_recommendations_immutable'])and not tgisinternal),'result and explanation records are immutable');
select ok((select pg_get_functiondef(p.oid)like'%SUM(score*weight)/SUM(maximum_score*weight)*100%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='complete_diagnostic_session'),'completion records the Gold Master formula explanation');
select ok((select pg_get_functiondef(p.oid)like'%qv.maximum_score*qv.weight%'and pg_get_functiondef(p.oid)like'%ar.value%score%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='complete_diagnostic_session'),'server computes score from frozen answers and versioned question weights');
select ok((select pg_get_functiondef(p.oid)like'%s.answer_manifest_hash%'and pg_get_functiondef(p.oid)like'%scoring_policy_snapshot%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='complete_diagnostic_session'),'result binds input and scoring policy snapshots');
select ok((select p.prosrc like'%s.status<>''SUBMITTED''%'and p.prosrc like'%s.audience<>''CLIENT''%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='complete_diagnostic_session'),'only submitted Client sessions can complete');
select ok((select pg_get_functiondef(p.oid)like'%CLIENT_OWNER%'and pg_get_functiondef(p.oid)like'%CLIENT_ADMIN%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='complete_diagnostic_session'),'completion enforces server-side organization roles');
select ok((select pg_get_functiondef(p.oid)like'%80%'and pg_get_functiondef(p.oid)like'%60%'and pg_get_functiondef(p.oid)like'%40%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='complete_diagnostic_session'),'versioned policy uses the required baseline thresholds');
select ok((select pg_get_functiondef(p.oid)like'%HEALTH_SCORE_%'and pg_get_functiondef(p.oid)like'%rating=''CRITICAL''%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='complete_diagnostic_session'),'blocking critical anomaly stays explicit');
select ok((select pg_get_functiondef(p.oid)like'%diagnostic_recommendations%'and pg_get_functiondef(p.oid)like'%diagnostic_opportunities%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='complete_diagnostic_session'),'non-good results create recommendation and opportunity atomically');
select ok((select pg_get_functiondef(p.oid)like'%status=''SUPERSEDED''%'and pg_get_functiondef(p.oid)like'%superseded_at%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='complete_diagnostic_session'),'recompute supersedes rather than overwrites history');
select ok((select pg_get_functiondef(p.oid)like'%begin_contract_command%'and pg_get_functiondef(p.oid)like'%finish_contract_command%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='complete_diagnostic_session'),'completion is idempotent');
select ok((select pg_get_functiondef(p.oid)like'%diagnostic.completed%'and pg_get_functiondef(p.oid)like'%DiagnosticCompletedV1%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='complete_diagnostic_session'),'completion writes audit and Outbox');
select ok((select pg_get_functiondef(p.oid)like'%ACCEPT%'and pg_get_functiondef(p.oid)like'%DEFER%'and pg_get_functiondef(p.oid)like'%REQUEST_RFQ%'and pg_get_functiondef(p.oid)like'%CLOSE%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='transition_diagnostic_opportunity'),'client opportunity actions are explicit');
select ok((select pg_get_functiondef(p.oid)like'%jsonb_array_length(o.missing_fields)>0%'and pg_get_functiondef(p.oid)like'%o.service_id is null%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='transition_diagnostic_opportunity'),'RFQ readiness requires service and complete information');
select ok((select pg_get_functiondef(p.oid)not like'%insert into public.service_requests%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='transition_diagnostic_opportunity'),'no service is ordered automatically');
select ok((select pg_get_functiondef(p.oid)like'%row_version<>p_expected_row_version%'and pg_get_functiondef(p.oid)like'%STALE_OPPORTUNITY%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='transition_diagnostic_opportunity'),'opportunity transition uses optimistic locking');
select ok((select pg_get_functiondef(p.oid)like'%diagnostic.opportunity.%'and pg_get_functiondef(p.oid)like'%event_outbox%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='transition_diagnostic_opportunity'),'opportunity actions are idempotent, audited and outboxed');
select ok((select count(*)>=6 from pg_indexes where schemaname='public'and(indexname like'diagnostic_%'or indexname='diagnostic_answers_expiry_idx')),'tenant, status, time and continuous-diagnostic access paths are indexed');

select*from finish();rollback;
